import { inject, Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { map, Observable } from 'rxjs';
import { environment } from '@env';
import { QrBill } from '@domain/models/qr-bill.model';
import { QrBillRepository } from '@domain/repositories/qr-bill.repository';
import { SalesInvoiceApiDto } from '../dtos/sales-invoice.dto';
import { QrBillMapper } from '../mappers/qr-bill.mapper';

/**
 * Swiss QR-bills are generated by the API from the invoices (`GET /sales/invoices/{id}/qr-bill` returns the
 * payment slip), so the list is the Swiss invoices that carry QR-bill data. There is no endpoint to create one.
 */
@Injectable()
export class QrBillHttpRepository implements QrBillRepository {
  private readonly http = inject(HttpClient);
  private readonly baseUrl = `${environment.apiBaseUrl}/sales/invoices`;

  getBills(): Observable<QrBill[]> {
    return this.http
      .get<{ data: SalesInvoiceApiDto[] }>(this.baseUrl, { params: { per_page: 100 } })
      .pipe(
        map((res) =>
          (res.data ?? [])
            .filter((invoice) => invoice.jurisdiction === 'CH' && !!invoice.qr_bill_data)
            .map((invoice) => QrBillMapper.fromInvoice(invoice)),
        ),
      );
  }
}
